before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>
enum class State { Ready, Done };
struct Session
{
    State state;
    int score;
};

int main()
{
    Session session{State::Ready, 2};
    session.state = State::Done;
    std::cout << std::boolalpha << (session.state == State::Done) << ' ' << session.score << "\n";
}

```

